toolScript:
import {
            FaceLandmarker,
            FilesetResolver
        } from "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3";
        // Global DOM Elements
        const video = document.getElementById('scanner-video');
        const canvasMP = document.getElementById('overlay-canvas'); // MediaPipe
        const canvasAPI = document.getElementById('face-api-canvas'); // FaceAPI
        const ctxMP = canvasMP.getContext('2d');
        const ctxAPI = canvasAPI.getContext('2d');
        const terminal = document.getElementById('terminal-content');
        const statusText = document.getElementById('status-text');
        const liveBtn = document.getElementById('live-btn');
        const scanBtn = document.getElementById('scan-btn');
        const scanLine = document.getElementById('scan-line');
        const resultBadge = document.getElementById('age-result');
        const liveIndicator = document.getElementById('live-indicator');
        const faceGuide = document.getElementById('face-guide');
        const tipsBox = document.getElementById('scan-tips');
        const tipsContent = document.getElementById('tip-content');
        const ingredientBox = document.getElementById('ingredient-recommendations');
        // State
        let isLive = false;
        let isScanning = false;
        let trackingActive = false;
        let useFaceApi = false;
        let stream = null;
        let faceLandmarker; // MediaPipe
        let lastVideoTime = -1;
        let faceApiInterval;
        let currentFacingMode = 'user';
        // Advanced State
        let autoCaptureEnabled = true;
        let stabilityFrameCount = 0;
        const STABILITY_THRESHOLD = 90; // ~3 seconds at 30fps
        let smoothedMetrics = null;
        const EMA_ALPHA = 0.12;
        let liveSessionSamples = [];
        // FaceAPI Averaging History
        const faceApiHistory = {
            age: [],
            gender: [],
            expressions: []
        };
        const MAX_HISTORY = 15;
        // Toggles
        let showHUD = true;
        let showGoldenRatio = false;
        // Logging Utility
        function log(msg, type = 'default') {
            const line = document.createElement('div');
            const time = new Date().toLocaleTimeString().split(' ')[0];
            const colorClass = type === 'success' ? 'text-green-400' : (type === 'error' ? 'text-red-500' : (type === 'purple' ? 'text-violet-400' : 'text-slate-400'));
            line.innerHTML = `<span class="opacity-30">[${time}]</span> <span class="${colorClass}">${msg}</span>`;
            terminal.appendChild(line);
            document.getElementById('terminal').scrollTop = document.getElementById('terminal').scrollHeight;
        }
        // --- 1. INITIALIZE MEDIAPIPE ---
        async function createFaceLandmarker() {
            log("Initializing Core 1: MediaPipe Vision...", "default");
            try {
                const filesetResolver = await FilesetResolver.forVisionTasks(
                    "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm"
                );
                faceLandmarker = await FaceLandmarker.createFromOptions(filesetResolver, {
                    baseOptions: {
                        modelAssetPath: `https://storage.googleapis.com/mediapipe-models/face_landmarker/face_landmarker/float16/1/face_landmarker.task`,
                        delegate: "GPU"
                    },
                    outputFaceBlendshapes: true,
                    runningMode: "VIDEO",
                    numFaces: 1
                });
                log("MediaPipe Core Ready.", "success");
            } catch (e) {
                log("MediaPipe Init Error: " + e, "error");
            }
        }
        createFaceLandmarker();
        // --- 2. INITIALIZE FACE-API (FIXED URL) ---
        async function loadFaceApiModels() {
            log("Initializing Core 2: Face-API Neural Nets...", "purple");
            const MODEL_URL = 'https://cdn.jsdelivr.net/npm/@vladmandic/face-api/model/';
            try {
                await faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL);
                await faceapi.nets.faceLandmark68Net.loadFromUri(MODEL_URL);
                await faceapi.nets.faceRecognitionNet.loadFromUri(MODEL_URL);
                await faceapi.nets.faceExpressionNet.loadFromUri(MODEL_URL);
                await faceapi.nets.ageGenderNet.loadFromUri(MODEL_URL);
                log("Face-API Models Loaded Successfully.", "purple");
                document.getElementById('faceapi-status').innerText = "Ready";
            } catch (err) {
                log("Face-API Load Failed: " + err, "error");
                log("Fallback: Continuing with MediaPipe only.", "default");
                const btn = document.getElementById('btn-faceapi');
                btn.disabled = true;
                btn.innerHTML = `Model Load Failed`;
                btn.classList.add('opacity-50', 'cursor-not-allowed');
            }
        }
        loadFaceApiModels();
        // --- WEBCAM HANDLING ---
        window.startWebcam = async function () {
            try {
                if (stream) {
                    stream.getTracks().forEach(track => track.stop());
                }
                stream = await navigator.mediaDevices.getUserMedia({
                    video: {
                        facingMode: currentFacingMode,
                        width: { ideal: 1280 },
                        height: { ideal: 720 }
                    }
                });
                video.srcObject = stream;
                // Flip video element horizontally only if user-facing
                if (currentFacingMode === 'user') {
                    video.style.transform = 'scaleX(-1)';
                } else {
                    video.style.transform = 'scaleX(1)';
                }
                video.onloadeddata = () => {
                    video.play();
                    video.style.display = 'block';
                    statusText.style.display = 'none';
                    faceGuide.style.display = 'none';
                    document.getElementById('live-btn').disabled = false;
                    document.getElementById('scan-btn').disabled = false;
                    trackingActive = true;
                    if (!isLive) window.toggleLiveMode(); // Auto-start if not already
                    log(`Webcam active (${currentFacingMode}). Engines engaging.`, "success");
                    document.getElementById('tracking-status').innerText = "Standby";
                    document.getElementById('tracking-status').className = "text-orange-500 font-bold uppercase";
                    predictWebcam();
                };
            } catch (err) {
                log("Camera Error: " + err, "error");
            }
        };
        window.switchCamera = async function () {
            currentFacingMode = currentFacingMode === 'user' ? 'environment' : 'user';
            log(`Switching to ${currentFacingMode} camera...`);
            await startWebcam();
        };
        // --- RENDER LOOP ---
        async function predictWebcam() {
            if (!trackingActive) return;
            // MediaPipe Logic (Per Frame)
            let results = undefined;
            if (faceLandmarker && video.readyState >= 2 && video.videoWidth > 0 && video.videoHeight > 0) {
                if (lastVideoTime !== video.currentTime) {
                    lastVideoTime = video.currentTime;
                    try {
                        results = faceLandmarker.detectForVideo(video, performance.now());
                    } catch (e) { }
                }
                // Prepare Canvases
                if (canvasMP.width !== video.clientWidth || canvasMP.height !== video.clientHeight) {
                    canvasMP.width = video.clientWidth;
                    canvasMP.height = video.clientHeight;
                    canvasAPI.width = video.clientWidth;
                    canvasAPI.height = video.clientHeight;
                }
                ctxMP.clearRect(0, 0, canvasMP.width, canvasMP.height);
                // For user facing camera, we want the drawing to match the mirrored video
                // For back camera, no mirror. 
                // MediaPipe coordinates are normalized 0-1. 
                // If video is CSS flipped (scaleX-1), we need to flip drawing too?
                // Actually, canvas context transformations are easier.
                ctxMP.save();
                if (currentFacingMode === 'user') {
                    ctxMP.translate(canvasMP.width, 0);
                    ctxMP.scale(-1, 1);
                }
                drawPassiveFaceGuide();
                if (results && results.faceLandmarks && results.faceLandmarks.length > 0) {
                    document.getElementById('points-val').innerText = "468";
                    document.getElementById('tracking-status').innerText = "Tracking";
                    document.getElementById('tracking-status').className = "text-green-500 font-bold uppercase";
                    const envStatus = checkEnvironment(results.faceLandmarks[0], results.faceBlendshapes[0]);
                    drawAnalyticalOverlay(results.faceLandmarks[0], envStatus);
                    if (isLive && !isScanning) {
                        const rawMetrics = calculateBiometrics(results.faceBlendshapes[0], results.faceLandmarks[0]);
                        if (rawMetrics) liveSessionSamples.push(rawMetrics);
                        if (!smoothedMetrics) {
                            smoothedMetrics = rawMetrics;
                        } else {
                            smoothedMetrics.age = (smoothedMetrics.age * (1 - EMA_ALPHA)) + (rawMetrics.age * EMA_ALPHA);
                            smoothedMetrics.structuralAge = (smoothedMetrics.structuralAge * (1 - EMA_ALPHA)) + (rawMetrics.structuralAge * EMA_ALPHA);
                            smoothedMetrics.softTissueAge = (smoothedMetrics.softTissueAge * (1 - EMA_ALPHA)) + (rawMetrics.softTissueAge * EMA_ALPHA);
                            smoothedMetrics.symmetry = (smoothedMetrics.symmetry * (1 - EMA_ALPHA)) + (parseFloat(rawMetrics.symmetry) * EMA_ALPHA);
                            smoothedMetrics.skin = (smoothedMetrics.skin * (1 - EMA_ALPHA)) + (parseFloat(rawMetrics.skin) * EMA_ALPHA);
                            smoothedMetrics.confidence = (smoothedMetrics.confidence * (1 - EMA_ALPHA)) + (rawMetrics.confidence * EMA_ALPHA);
                            smoothedMetrics.faceShape = rawMetrics.faceShape;
                            smoothedMetrics.gender = rawMetrics.gender;
                            smoothedMetrics.canthalTilt = rawMetrics.canthalTilt;
                            smoothedMetrics.lipVolume = rawMetrics.lipVolume;
                            smoothedMetrics.tip = rawMetrics.tip;
                            smoothedMetrics.ingredients = rawMetrics.ingredients;
                        }
                        // Auto Capture Logic
                        if (autoCaptureEnabled && envStatus.message === "PERFECT") {
                            stabilityFrameCount++;
                        } else {
                            stabilityFrameCount = Math.max(0, stabilityFrameCount - 5);
                        }
                        if (stabilityFrameCount > STABILITY_THRESHOLD) {
                            stabilityFrameCount = 0;
                            toggleLiveMode();
                            log("Auto-Capture Triggered: Optimal Pose Detected.", "success");
                        }
                        document.getElementById('result-type').innerText = "Real-Time Biometric Stream";
                        updateDisplay(smoothedMetrics);
                    }
                } else {
                    document.getElementById('points-val').innerText = "0";
                    document.getElementById('tracking-status').innerText = "Searching...";
                    document.getElementById('tracking-status').className = "text-orange-400 font-bold uppercase";
                    if (trackingActive) {
                        ctxMP.font = "bold 16px Inter";
                        ctxMP.fillStyle = "rgba(255,255,255,0.7)";
                        ctxMP.textAlign = "center";
                        // Draw text correctly oriented
                        ctxMP.save();
                        if (currentFacingMode === 'user') {
                            ctxMP.scale(-1, 1);
                            ctxMP.translate(-canvasMP.width, 0);
                        }
                        ctxMP.fillText("SEARCHING FOR FACE...", canvasMP.width / 2, canvasMP.height / 2);
                        ctxMP.restore();
                    }
                }
                ctxMP.restore(); // Restore context state from mirroring
            }
            requestAnimationFrame(predictWebcam);
        }
        // --- FACE API LOOP (THROTTLED & AVERAGED) ---
        async function runFaceApiDetection() {
            if (!useFaceApi || !video.paused && !video.srcObject) return;
            if (!faceapi.nets.tinyFaceDetector.params) return;
            try {
                const detections = await faceapi.detectAllFaces(video, new faceapi.TinyFaceDetectorOptions())
                    .withFaceLandmarks()
                    .withFaceExpressions()
                    .withAgeAndGender();
                ctxAPI.clearRect(0, 0, canvasAPI.width, canvasAPI.height);
                // Handle mirroring for API canvas too
                ctxAPI.save();
                if (currentFacingMode === 'user') {
                    ctxAPI.translate(canvasAPI.width, 0);
                    ctxAPI.scale(-1, 1);
                }
                const resizedDetections = faceapi.resizeResults(detections, { width: canvasAPI.width, height: canvasAPI.height });
                if (resizedDetections.length > 0) {
                    const d = resizedDetections[0];
                    // AVERAGING LOGIC
                    faceApiHistory.age.push(d.age);
                    if (faceApiHistory.age.length > MAX_HISTORY) faceApiHistory.age.shift();
                    const avgAge = faceApiHistory.age.reduce((a, b) => a + b, 0) / faceApiHistory.age.length;
                    // Custom Drawing
                    const box = d.detection.box;
                    ctxAPI.strokeStyle = '#7c3aed'; // Violet-600
                    ctxAPI.lineWidth = 2;
                    ctxAPI.strokeRect(box.x, box.y, box.width, box.height);
                    ctxAPI.fillStyle = '#7c3aed';
                    d.landmarks.positions.forEach(p => {
                        ctxAPI.beginPath(); ctxAPI.arc(p.x, p.y, 1.5, 0, 2 * Math.PI); ctxAPI.fill();
                    });
                    const expressions = d.expressions;
                    const sortedExpr = Object.keys(expressions).sort((a, b) => expressions[b] - expressions[a]);
                    document.getElementById('api-age').innerText = Math.round(avgAge);
                    document.getElementById('api-gender').innerText = `${d.gender} (${Math.round(d.genderProbability * 100)}%)`;
                    document.getElementById('api-expr').innerText = sortedExpr[0].toUpperCase();
                    // Show label on canvas
                    const drawBox = new faceapi.draw.DrawTextField(
                        [`${Math.round(avgAge)} years`, `${d.gender}`],
                        d.detection.box.bottomLeft
                    );
                    drawBox.draw(canvasAPI);
                }
                ctxAPI.restore();
            } catch (err) { }
        }
        // --- DRAWING HELPERS ---
        function drawPassiveFaceGuide() {
            const cx = canvasMP.width / 2;
            const cy = canvasMP.height / 2;
            const rx = canvasMP.width * 0.25;
            const ry = canvasMP.height * 0.35;
            ctxMP.save();
            ctxMP.strokeStyle = 'rgba(255, 255, 255, 0.15)';
            ctxMP.lineWidth = 2;
            ctxMP.setLineDash([15, 10]);
            ctxMP.beginPath(); ctxMP.ellipse(cx, cy, rx, ry, 0, 0, 2 * Math.PI); ctxMP.stroke();
            ctxMP.setLineDash([]); ctxMP.strokeStyle = 'rgba(255, 255, 255, 0.1)';
            ctxMP.beginPath(); ctxMP.moveTo(cx - 20, cy); ctxMP.lineTo(cx + 20, cy); ctxMP.moveTo(cx, cy - 20); ctxMP.lineTo(cx, cy + 20); ctxMP.stroke();
            // Text needs un-mirroring if mirrored
            ctxMP.save();
            if (currentFacingMode === 'user') { ctxMP.scale(-1, 1); ctxMP.translate(-canvasMP.width, 0); } // Un-mirror for text
            // wait, relative coordinates are hard. Let's just skip text on guide for now or simple center text
            // ctxMP.fillStyle = 'rgba(255, 255, 255, 0.5)'; ctxMP.font = '10px "JetBrains Mono", monospace'; ctxMP.textAlign = 'center';
            // if(!autoCaptureEnabled) ctxMP.fillText("ALIGN FACE HERE", canvasMP.width/2, cy + ry + 20);
            ctxMP.restore();
            ctxMP.restore();
        }
        function getAverageFaceBrightness(landmarks) {
            const points = [10, 1, 234, 454, 152];
            let total = 0; let samples = 0;
            points.forEach(idx => {
                const x = Math.floor(landmarks[idx].x * canvasMP.width);
                const y = Math.floor(landmarks[idx].y * canvasMP.height);
                if (x > 5 && x < canvasMP.width - 5 && y > 5 && y < canvasMP.height - 5) {
                    const data = ctxMP.getImageData(x - 2, y - 2, 5, 5).data;
                    for (let i = 0; i < data.length; i += 4) {
                        const r = data[i]; const g = data[i + 1]; const b = data[i + 2];
                        if (r > 10 || g > 10 || b > 10) { total += (r + g + b) / 3; samples++; }
                    }
                }
            });
            return samples > 0 ? total / samples : 100;
        }
        function detectGlassesHeuristic(landmarks, skinBrightness) {
            const eyeL_x = Math.floor(landmarks[468].x * canvasMP.width);
            const eyeL_y = Math.floor(landmarks[468].y * canvasMP.height);
            let eyeBrightness = skinBrightness;
            if (eyeL_x > 0 && eyeL_x < canvasMP.width && eyeL_y > 0 && eyeL_y < canvasMP.height) {
                const p = ctxMP.getImageData(eyeL_x, eyeL_y, 1, 1).data;
                eyeBrightness = (p[0] + p[1] + p[2]) / 3;
            }
            if (eyeBrightness > skinBrightness + 70) return true;
            return false;
        }
        function checkEnvironment(landmarks, blendshapes) {
            let status = { message: "PERFECT", color: "#4ade80", yaw: 0, pitch: 0, roll: 0, lighting: "Good", glasses: false };
            let yaw = 0, pitch = 0, roll = 0;
            if (blendshapes && blendshapes.categories) {
                yaw = blendshapes.categories.find(c => c.categoryName === 'headYaw')?.score || 0;
                pitch = blendshapes.categories.find(c => c.categoryName === 'headPitch')?.score || 0;
                roll = blendshapes.categories.find(c => c.categoryName === 'headRoll')?.score || 0;
            }
            status.yaw = yaw; status.pitch = pitch; status.roll = roll;
            const brightness = getAverageFaceBrightness(landmarks);
            if (brightness < 25) { status.message = "TOO DARK (Low Light)"; status.color = "#f87171"; status.lighting = "Low"; }
            else if (brightness > 245) { status.message = "TOO BRIGHT "; status.color = "#f87171"; status.lighting = "High"; }
            if (detectGlassesHeuristic(landmarks, brightness)) { status.message = "REMOVE GLASSES "; status.color = "#fbbf24"; status.glasses = true; }
            if (Math.abs(yaw) > 0.15) { status.message = yaw > 0 ? "TURN RIGHT ⮞" : "⮜ TURN LEFT"; status.color = "#facc15"; }
            else if (Math.abs(pitch) > 0.15) { status.message = pitch > 0 ? "LOOK UP " : "LOOK DOWN "; status.color = "#facc15"; }
            else if (Math.abs(roll) > 0.1) { status.message = "STRAIGHTEN HEAD"; status.color = "#facc15"; }
            const irisDist = Math.sqrt(Math.pow(landmarks[468].x - landmarks[473].x, 2) + Math.pow(landmarks[468].y - landmarks[473].y, 2));
            if (irisDist < 0.12) { status.message = "MOVE CLOSER ⊕"; status.color = "#f87171"; }
            else if (irisDist > 0.25) { status.message = "MOVE BACK ⊖"; status.color = "#f87171"; }
            return status;
        }
        function drawAnalyticalOverlay(landmarks, envStatus) {
            ctxMP.lineWidth = 1;
            const p = (i) => ({ x: landmarks[i].x * canvasMP.width, y: landmarks[i].y * canvasMP.height });
            if (showGoldenRatio) {
                for (let i = 0; i < landmarks.length; i++) {
                    const pt = p(i);
                    const z = landmarks[i].z;
                    const depth = Math.max(0, Math.min(1, (z + 0.1) * 5));
                    const alpha = 1 - depth;
                    ctxMP.fillStyle = `rgba(56, 189, 248, ${Math.max(0.1, alpha * 0.6)})`;
                    ctxMP.beginPath(); ctxMP.arc(pt.x, pt.y, 1, 0, 2 * Math.PI); ctxMP.fill();
                }
                ctxMP.strokeStyle = 'rgba(255, 215, 0, 0.3)'; ctxMP.lineWidth = 1;
                const browY = (p(107).y + p(336).y) / 2;
                ctxMP.beginPath(); ctxMP.moveTo(0, browY); ctxMP.lineTo(canvasMP.width, browY); ctxMP.stroke();
                const noseY = p(2).y;
                ctxMP.beginPath(); ctxMP.moveTo(0, noseY); ctxMP.lineTo(canvasMP.width, noseY); ctxMP.stroke();
                const chinY = p(152).y;
                ctxMP.beginPath(); ctxMP.moveTo(0, chinY); ctxMP.lineTo(canvasMP.width, chinY); ctxMP.stroke();
                const midX = p(168).x;
                ctxMP.beginPath(); ctxMP.moveTo(midX, 0); ctxMP.lineTo(midX, canvasMP.height); ctxMP.stroke();
                ctxMP.fillStyle = 'rgba(255, 215, 0, 0.8)'; ctxMP.font = "10px monospace";
                // ctxMP.fillText("3D MESH + φ RATIO", 20, 40); // Text issue with mirror, skipping for robustness
            }
            // Triangle of Youth
            ctxMP.beginPath();
            const cheekL = p(234); const cheekR = p(454); const chin = p(152);
            ctxMP.moveTo(cheekL.x, cheekL.y); ctxMP.lineTo(cheekR.x, cheekR.y); ctxMP.lineTo(chin.x, chin.y); ctxMP.closePath();
            ctxMP.strokeStyle = 'rgba(251, 146, 60, 0.5)'; ctxMP.stroke();
            const eyeL = p(468); const eyeR = p(473);
            ctxMP.beginPath(); ctxMP.arc(eyeL.x, eyeL.y, 15, 0, 2 * Math.PI); ctxMP.strokeStyle = 'rgba(56, 189, 248, 0.6)'; ctxMP.stroke();
            ctxMP.beginPath(); ctxMP.arc(eyeR.x, eyeR.y, 15, 0, 2 * Math.PI); ctxMP.stroke();
            // Jawline
            ctxMP.beginPath();
            const jawIndices = [234, 93, 132, 58, 172, 136, 150, 149, 176, 148, 152, 377, 400, 378, 379, 365, 397, 288, 361, 323, 454];
            const start = p(jawIndices[0]);
            ctxMP.moveTo(start.x, start.y);
            for (let i = 1; i < jawIndices.length; i++) { const point = p(jawIndices[i]); ctxMP.lineTo(point.x, point.y); }
            ctxMP.strokeStyle = 'rgba(255, 255, 255, 0.3)'; ctxMP.stroke();
            if (showHUD) {
                // To draw text correctly, we must un-mirror the context if it was mirrored
                ctxMP.save();
                if (currentFacingMode === 'user') {
                    ctxMP.scale(-1, 1);
                    ctxMP.translate(-canvasMP.width, 0);
                }
                ctxMP.font = "900 24px 'Inter', sans-serif"; ctxMP.textAlign = "center";
                const msgX = canvasMP.width / 2; const msgY = canvasMP.height - 50;
                ctxMP.shadowColor = "rgba(0,0,0,0.8)"; ctxMP.shadowBlur = 4; ctxMP.shadowOffsetX = 2; ctxMP.shadowOffsetY = 2;
                ctxMP.fillStyle = envStatus.color; ctxMP.fillText(envStatus.message, msgX, msgY);
                // Checklist
                if (envStatus.message === "PERFECT" || envStatus.message === "ALIGN FACE") {
                    ctxMP.textAlign = "left"; ctxMP.font = "700 12px 'JetBrains Mono', monospace";
                    ctxMP.shadowColor = "black"; ctxMP.shadowBlur = 2;
                    const pad = 20;
                    ctxMP.fillStyle = "rgba(255,255,255,0.9)"; ctxMP.fillText("SEATING CHECKLIST:", pad, canvasMP.height / 2 - 40);
                    ctxMP.fillStyle = envStatus.glasses ? "#fbbf24" : "rgba(255,255,255,0.9)"; ctxMP.fillText("1. REMOVE GLASSES", pad, canvasMP.height / 2 - 20);
                    ctxMP.fillStyle = "rgba(255,255,255,0.9)"; ctxMP.fillText("2. NEUTRAL EXPRESSION", pad, canvasMP.height / 2);
                    ctxMP.fillText("3. NO HANDS ON FACE", pad, canvasMP.height / 2 + 20);
                    ctxMP.fillText("4. HAIR BACK", pad, canvasMP.height / 2 + 40);
                    ctxMP.shadowBlur = 0;
                }
                // Lighting
                ctxMP.fillStyle = "rgba(0,0,0,0.5)"; ctxMP.roundRect(10, 10, 100, 30, 8); ctxMP.fill();
                ctxMP.fillStyle = envStatus.lighting === "Low" || envStatus.lighting === "High" ? "#f87171" : "#4ade80";
                ctxMP.textAlign = "left"; ctxMP.font = "bold 10px monospace";
                ctxMP.fillText(`LIGHT: ${envStatus.lighting}`, 20, 28);
                ctxMP.restore();
                if (autoCaptureEnabled && isLive && stabilityFrameCount > 0) {
                    const cx = canvasMP.width / 2; const cy = canvasMP.height / 2;
                    const radius = canvasMP.height * 0.38;
                    const startAngle = -Math.PI / 2;
                    const endAngle = startAngle + ((Math.PI * 2) * (stabilityFrameCount / STABILITY_THRESHOLD));
                    ctxMP.beginPath(); ctxMP.arc(cx, cy, radius, startAngle, endAngle);
                    ctxMP.strokeStyle = '#4ade80'; ctxMP.lineWidth = 8; ctxMP.lineCap = 'round'; ctxMP.stroke();
                }
            }
        }
        function calculateBiometrics(blendshapes, landmarks) {
            if (!blendshapes || !blendshapes.categories) return null;
            const scores = {};
            blendshapes.categories.forEach(c => scores[c.categoryName] = c.score);
            const dist = (i1, i2) => Math.sqrt(Math.pow(landmarks[i1].x - landmarks[i2].x, 2) + Math.pow(landmarks[i1].y - landmarks[i2].y, 2));
            const jawWidth = dist(234, 454); const cheekWidth = dist(127, 356); const faceHeight = dist(10, 152);
            const facialIndex = faceHeight / cheekWidth;
            let genderScore = 0;
            const jawCheekRatio = jawWidth / cheekWidth;
            if (jawCheekRatio > 0.88) genderScore += 2; else if (jawCheekRatio < 0.82) genderScore -= 2;
            const browDist = Math.abs(landmarks[66].y - landmarks[473].y);
            if ((browDist / faceHeight) < 0.035) genderScore += 1.5; else if ((browDist / faceHeight) > 0.05) genderScore -= 1.5;
            const gender = genderScore > 0 ? "Male" : "Female";
            let structuralAge = 22;
            const eyeDist = dist(33, 263);
            if ((jawWidth / eyeDist) > 2.2) structuralAge += 5;
            const leftTilt = landmarks[33].y - landmarks[133].y;
            let canthalTilt = "Neutral"; let tiltAgeMod = 0;
            if (leftTilt < -0.015) { canthalTilt = "Positive (Youthful)"; tiltAgeMod = -4; }
            else if (leftTilt > 0.01) { canthalTilt = "Negative (Mature)"; tiltAgeMod = +5; }
            const lipRatio = dist(0, 17) / dist(61, 291);
            let lipVol = "Medium"; let lipAgeMod = 0;
            if (lipRatio < 0.30) { lipVol = "Thin"; lipAgeMod = +4; }
            else if (lipRatio > 0.45) { lipVol = "Full"; lipAgeMod = -3; if (lipRatio > 0.5) lipAgeMod -= 2; }
            const nasolabial = (scores.noseSneerLeft + scores.noseSneerRight) / 2;
            const mouthDroop = (scores.mouthFrownLeft + scores.mouthFrownRight) / 2;
            let softTissueAge = 22 + tiltAgeMod + lipAgeMod;
